CREATE OR REPLACE FUNCTION pg_temp.river_entity(t text, c text, n text, proposed uuid)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE ids uuid[]; resolved uuid;
BEGIN
 IF t NOT IN ('industries','domains','role_families','role') THEN RAISE EXCEPTION 'Unsupported catalog table'; END IF;
 EXECUTE format('SELECT array_agg(id) FROM public.%I WHERE code=$1 OR name=$2',t) INTO ids USING c,n;
 IF cardinality(ids)>1 THEN RAISE EXCEPTION 'Ambiguous code/name identity for %: % / %',t,c,n; END IF;
 IF cardinality(ids)=1 THEN RETURN ids[1]; END IF;
 EXECUTE format('INSERT INTO public.%I (id,code,name) VALUES ($1,$2,$3) RETURNING id',t)
 INTO resolved USING proposed,c,n;
 RETURN resolved;
END $$;

DO $role$
DECLARE r jsonb := '{"industry_code": "IND_WAT_001", "industry_name": "Water & Environmental Services", "domain_code": "WAT_D02", "domain_name": "Water & Environmental Engineering", "family_code": "WAT_RF02", "family_name": "Water Treatment Engineer", "role_code": "RMR-ROLE-02", "role_name": "Water Cleaning Engineer", "description": "Designs or improves methods for separating unwanted substances from water and checks whether treatment claims are supported. Future role: Water Treatment Engineer; school activities are introductory demonstrations.", "observable_behaviours": "Transfer and Filter: decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings; Calculate Salt Solution Concentration: identify mass and volume from the same mixture, apply the taught concentration expression and record the correct units; Inspect What Paper Filtration Retains: distinguish source solutions, observe what the paper retains, and document the filtrate without merging their samples; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision", "role_work_context": "A water-treatment engineering team examines how settling, decanting and filters work and whether equipment claims are supported. School experiments are illustrative rather than treatment-plant certification.", "typical_work_activities": "Trace settled soil, decanting and paper-filter operations by vessel ID; Compare suspended soil with dissolved salt; Link mass and volume when describing solution concentration; Examine whether the filter advertisement exceeds the evidence", "role_output_evidence": "Decanting and filtration process record; Salt-solution concentration working; Separate soil and salt filtration log; Filter-claim assessment with evidence limits; Learning modules: RMR-CAP-L01-M02 - Transfer and Filter (Core, step 1), RMR-CAP-L04-M01 - Calculate Salt Solution Concentration (Important, step 2), RMR-CAP-L04-M02 - Inspect What Paper Filtration Retains (Important, step 3), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Supporting, step 4)", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "Realistic work involves physical treatment processes and equipment; Investigative work checks measurements and limitations; Conventional discipline makes calculations and process records traceable.", "degree_gate": "Mandatory", "direct_degree_mapping": "B.Tech. Chemical Engineering; B.Tech. Environmental Engineering; B.Tech. Civil Engineering", "apt_verbal_reasoning": 64, "apt_logical_reasoning": 86, "apt_numerical_reasoning": 88, "apt_data_interpretation": 82, "apt_pattern_recognition": 75, "apt_spatial_reasoning": 85, "big5_openness": 5, "big5_conscientiousness": 5, "big5_extraversion": 3, "big5_agreeableness": 3, "big5_emotional_stability": 4, "value_impact": 5, "value_status": 4, "value_autonomy": 4, "value_security": 4, "value_financial": 4, "value_lifestyle": 3, "value_creativity": 5, "value_leadership": 4, "aptitude_areas": "Numerical Reasoning|Logical Reasoning|Spatial Reasoning", "aptitude_rationale": "Water Cleaning Engineer uses numerical reasoning, logical reasoning, spatial reasoning to trace settled soil, decanting and paper-filter operations by vessel id, compare suspended soil with dissolved salt, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude.", "big_five_traits": "Openness|Conscientiousness|Emotional Stability", "big_five_rationale": "Water Cleaning Engineer benefits from openness, conscientiousness, emotional stability when performing compare suspended soil with dissolved salt and following through on filter-claim assessment with evidence limits. Traits guide supportive coaching, not exclusion.", "work_values_list": "Impact|Creativity|Autonomy", "work_values_rationale": "This pathway may reward impact, creativity, autonomy through the work of trace settled soil, decanting and paper-filter operations by vessel id and producing a clear decanting and filtration process record. These are possible work priorities, not salary or job guarantees.", "profile": {"description": "Designs or improves methods for separating unwanted substances from water and checks whether treatment claims are supported. Future role: Water Treatment Engineer; school activities are introductory demonstrations.", "observable_behaviours": "Transfer and Filter: decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings; Calculate Salt Solution Concentration: identify mass and volume from the same mixture, apply the taught concentration expression and record the correct units; Inspect What Paper Filtration Retains: distinguish source solutions, observe what the paper retains, and document the filtrate without merging their samples; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision", "role_work_context": "A water-treatment engineering team examines how settling, decanting and filters work and whether equipment claims are supported. School experiments are illustrative rather than treatment-plant certification.", "typical_work_activities": "Trace settled soil, decanting and paper-filter operations by vessel ID; Compare suspended soil with dissolved salt; Link mass and volume when describing solution concentration; Examine whether the filter advertisement exceeds the evidence", "role_output_evidence": "Decanting and filtration process record; Salt-solution concentration working; Separate soil and salt filtration log; Filter-claim assessment with evidence limits; Learning modules: RMR-CAP-L01-M02 - Transfer and Filter (Core, step 1), RMR-CAP-L04-M01 - Calculate Salt Solution Concentration (Important, step 2), RMR-CAP-L04-M02 - Inspect What Paper Filtration Retains (Important, step 3), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Supporting, step 4)", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "Realistic work involves physical treatment processes and equipment; Investigative work checks measurements and limitations; Conventional discipline makes calculations and process records traceable.", "degree_gate": "Mandatory", "direct_degree_mapping": "B.Tech. Chemical Engineering; B.Tech. Environmental Engineering; B.Tech. Civil Engineering", "riasec_code_string": "RIC", "aptitude_profile": {"verbal_reasoning": 64, "logical_reasoning": 86, "numerical_reasoning": 88, "data_interpretation": 82, "pattern_recognition": 75, "spatial_reasoning": 85}, "big_five_profile": {"openness": 5, "conscientiousness": 5, "extraversion": 3, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 4, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 3, "creativity": 5, "leadership": 4}, "aptitude_assessment": {"areas": ["Numerical Reasoning", "Logical Reasoning", "Spatial Reasoning"], "rationale": "Water Cleaning Engineer uses numerical reasoning, logical reasoning, spatial reasoning to trace settled soil, decanting and paper-filter operations by vessel id, compare suspended soil with dissolved salt, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Openness", "Conscientiousness", "Emotional Stability"], "rationale": "Water Cleaning Engineer benefits from openness, conscientiousness, emotional stability when performing compare suspended soil with dissolved salt and following through on filter-claim assessment with evidence limits. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Creativity", "Autonomy"], "rationale": "This pathway may reward impact, creativity, autonomy through the work of trace settled soil, decanting and paper-filter operations by vessel id and producing a clear decanting and filtration process record. These are possible work priorities, not salary or job guarantees."}}, "embedding_text": "ROLE\nName: Water Cleaning Engineer\n\nCAREER CONTEXT\nIndustry: Water & Environmental Services\nDomain: Water & Environmental Engineering\nRole Family: Water Treatment Engineer\n\nROLE SUMMARY\nDesigns or improves methods for separating unwanted substances from water and checks whether treatment claims are supported. Future role: Water Treatment Engineer; school activities are introductory demonstrations.\n\nWORK CONTEXT\nA water-treatment engineering team examines how settling, decanting and filters work and whether equipment claims are supported. School experiments are illustrative rather than treatment-plant certification.\n\nTYPICAL WORK ACTIVITIES\nTrace settled soil, decanting and paper-filter operations by vessel ID; Compare suspended soil with dissolved salt; Link mass and volume when describing solution concentration; Examine whether the filter advertisement exceeds the evidence\n\nKEY RESPONSIBILITIES & ACTIONS\nTransfer and Filter: decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings; Calculate Salt Solution Concentration: identify mass and volume from the same mixture, apply the taught concentration expression and record the correct units; Inspect What Paper Filtration Retains: distinguish source solutions, observe what the paper retains, and document the filtrate without merging their samples; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision\n\nDELIVERABLES & OUTPUTS\nDecanting and filtration process record; Salt-solution concentration working; Separate soil and salt filtration log; Filter-claim assessment with evidence limits; Learning modules: RMR-CAP-L01-M02 - Transfer and Filter (Core, step 1), RMR-CAP-L04-M01 - Calculate Salt Solution Concentration (Important, step 2), RMR-CAP-L04-M02 - Inspect What Paper Filtration Retains (Important, step 3), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Supporting, step 4)\n\nINTEREST AND WORK-STYLE ALIGNMENT\nRealistic work involves physical treatment processes and equipment; Investigative work checks measurements and limitations; Conventional discipline makes calculations and process records traceable.\n\nAPTITUDE ALIGNMENT\nKey areas: Numerical Reasoning, Logical Reasoning, Spatial Reasoning\nReadiness: Water Cleaning Engineer uses numerical reasoning, logical reasoning, spatial reasoning to trace settled soil, decanting and paper-filter operations by vessel id, compare suspended soil with dissolved salt, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude.\n\nBEHAVIOURAL ALIGNMENT\nKey traits: Openness, Conscientiousness, Emotional Stability\nWork style: Water Cleaning Engineer benefits from openness, conscientiousness, emotional stability when performing compare suspended soil with dissolved salt and following through on filter-claim assessment with evidence limits. Traits guide supportive coaching, not exclusion.\n\nWORK-VALUE ALIGNMENT\nKey values: Impact, Creativity, Autonomy\nMotivation: This pathway may reward impact, creativity, autonomy through the work of trace settled soil, decanting and paper-filter operations by vessel id and producing a clear decanting and filtration process record. These are possible work priorities, not salary or job guarantees.\n\nEDUCATION AND ELIGIBILITY\nGate: Mandatory\nStreams: B.Tech. Chemical Engineering; B.Tech. Environmental Engineering; B.Tech. Civil Engineering\n"}'::jsonb;
 i uuid; d uuid; f uuid; roleid uuid; scopeid uuid; familyid uuid; contextid uuid; existing jsonb;
BEGIN

 i:=pg_temp.river_entity('industries',r->>'industry_code',r->>'industry_name','081cf05d-7a89-5c4a-897f-bde339d91318'::uuid);
 d:=pg_temp.river_entity('domains',r->>'domain_code',r->>'domain_name','44476b2f-c955-57ce-9a2d-0299acb27cd5'::uuid);
 f:=pg_temp.river_entity('role_families',r->>'family_code',r->>'family_name','58a70df4-fe41-571e-af3e-26c7bf2f3fcc'::uuid);
 roleid:=pg_temp.river_entity('role',r->>'role_code',r->>'role_name','7404d4d3-34da-5fbd-a8f4-afbedc9acdd8'::uuid);

 SELECT id INTO scopeid FROM public.industry_domains WHERE industry_id=i AND domain_id=d;
 IF scopeid IS NULL THEN
  INSERT INTO public.industry_domains(id,industry_id,domain_id) VALUES ('054710f3-c70d-5e64-a956-65f0f9d91f00',i,d) RETURNING id INTO scopeid;
 END IF;
 SELECT id INTO familyid FROM public.role_family_domains WHERE role_family_id=f AND industry_domain_id=scopeid;
 IF familyid IS NULL THEN
  INSERT INTO public.role_family_domains(id,role_family_id,industry_domain_id) VALUES ('c5f73e99-5223-587b-bd62-e92d4fa7c659',f,scopeid) RETURNING id INTO familyid;
 END IF;
 SELECT id INTO contextid FROM public.role_family_roles WHERE role_family_domain_id=familyid AND role_id=roleid;
 IF contextid IS NOT NULL THEN
  SELECT to_jsonb(x) INTO existing FROM public.role_family_roles x WHERE id=contextid;
  IF NOT existing @> (r->'profile') OR existing->>'is_active' IS DISTINCT FROM 'true' THEN
   RAISE EXCEPTION 'Existing role context differs from workbook or is inactive: %. Review before changing production.',r->>'role_name';
