h supervised classroom cases.", "roles": {"entry": ["Forensic Scientist", "Crime Lab Analyst"], "mid": []}, "domains": ["Forensic Science"], "educationPathways": ["B.Sc Forensic Science"], "recommendedPrograms": ["B.Sc Forensic Science"], "futureOutlook": "Exploratory school demo; further education and supervised training are required.", "evidence": {"interest": "Investigative, Conventional and Realistic interests in the authored demo profile.", "aptitude": "Authored demonstration baseline; not a measured learner result.", "personality": "Curiosity, careful records and considerate teamwork."}}], "specificOptions": {"highFit": [{"name": "Water Project Manager", "roleCode": "RMR-ROLE-07", "occupationId": null, "whyThisRole": "Your curiosity about science, careful observation and interest in environmental impact support exploring water treatment, river protection and project planning.", "educationPathways": ["B.Tech Civil Engineering", "B.Tech Environmental Engineering"]}, {"name": "Water Plant Designer", "roleCode": "RMR-ROLE-09", "occupationId": null, "whyThisRole": "Your curiosity about science, careful observation and interest in environmental impact support exploring water treatment, river protection and project planning.", "educationPathways": ["B.Tech Civil Engineering", "B.Tech Environmental Engineering"]}, {"name": "River Protection Planner", "roleCode": "RMR-ROLE-15", "occupationId": null, "whyThisRole": "Your curiosity about science, careful observation and interest in environmental impact support exploring water treatment, river protection and project planning.", "educationPathways": ["B.Tech Civil Engineering", "B.Tech Environmental Engineering"]}], "mediumFit": [{"name": "Agricultural Scientist", "roleCode": "DEMO_SCH_ROLE01", "occupationId": null, "whyThisRole": "Biology, chemistry and data interpretation provide a starting point for exploring agricultural science, food technology and food-quality analysis.", "educationPathways": ["B.Sc Agriculture", "B.Tech Food Technology"]}, {"name": "Food Technologist", "roleCode": "DEMO_SCH_ROLE02", "occupationId": null, "whyThisRole": "Biology, chemistry and data interpretation provide a starting point for exploring agricultural science, food technology and food-quality analysis.", "educationPathways": ["B.Sc Agriculture", "B.Tech Food Technology"]}, {"name": "Food Quality Analyst", "roleCode": "DEMO_SCH_ROLE03", "occupationId": null, "whyThisRole": "Biology, chemistry and data interpretation provide a starting point for exploring agricultural science, food technology and food-quality analysis.", "educationPathways": ["B.Sc Agriculture", "B.Tech Food Technology"]}], "exploreLater": [{"name": "Forensic Scientist", "roleCode": "DEMO_SCH_ROLE04", "occupationId": null, "whyThisRole": "Logical reasoning, careful records and scientific curiosity can support exploring forensic investigation and laboratory evidence through supervised classroom cases.", "educationPathways": ["B.Sc Forensic Science"]}, {"name": "Crime Lab Analyst", "roleCode": "DEMO_SCH_ROLE05", "occupationId": null, "whyThisRole": "Logical reasoning, careful records and scientific curiosity can support exploring forensic investigation and laboratory evidence through supervised classroom cases.", "educationPathways": ["B.Sc Forensic Science"]}]}}'::jsonb;
 cluster jsonb; option jsonb; opts jsonb; groups jsonb := '{}'::jsonb; rebuilt jsonb := '[]'::jsonb;
 ids jsonb; context_ids uuid[]; context_id uuid; group_name text; affected integer;
 summary text:='Science — PCMB can help you explore water treatment, river protection and project planning while keeping agriculture, food technology and forensic science open as future study options. Build your scientific reasoning through supervised experiments, clear calculations and careful evidence records, and discuss subject choices with your teachers and family. These are exploratory demonstration pathways, not confirmed career outcomes.';
BEGIN
 -- Resolve actual IDs instead of assuming local fixture UUIDs.
 FOREACH group_name IN ARRAY ARRAY['highFit','mediumFit','exploreLater'] LOOP
  opts:='[]'::jsonb; ids:='[]'::jsonb;
  FOR option IN SELECT value FROM jsonb_array_elements(career->'specificOptions'->group_name) LOOP
   SELECT array_agg(ctx.id) INTO context_ids FROM public.role_family_roles ctx
   JOIN public.role ro ON ro.id=ctx.role_id
   WHERE ro.code=option->>'roleCode' AND ctx.is_active;
   IF cardinality(context_ids) IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'Missing or ambiguous demo role context %. Apply development 02_role_catalog.sql and 12_excel_school_roles.sql first.',option->>'name';
   END IF;
   context_id:=context_ids[1];
   option:=jsonb_set(option,'{occupationId}',to_jsonb(context_id::text));
   option:=jsonb_set(option,'{riasecCode}',to_jsonb((SELECT riasec_code_string FROM public.role_family_roles WHERE id=context_id)));
   opts:=opts||jsonb_build_array(option); ids:=ids||jsonb_build_array(context_id::text);
  END LOOP;
  groups:=jsonb_set(groups,ARRAY[group_name],opts);
  cluster:=career->'clusters'->(CASE group_name WHEN 'highFit' THEN 0 WHEN 'mediumFit' THEN 1 ELSE 2 END);
  rebuilt:=rebuilt||jsonb_build_array(jsonb_set(cluster,'{occupationIds}',ids));
 END LOOP;
 career:=jsonb_build_object('clusters',rebuilt,'specificOptions',groups);
 UPDATE public.personal_assessment_results SET
  career_fit=career, overall_summary=summary,
  skill_gap=coalesce(skill_gap,'{}'::jsonb)||jsonb_build_object(
    'recommendedTrack',rebuilt->0->>'title',
    'learningTracks',(SELECT jsonb_agg(jsonb_build_object('track',x->>'title','suggestedIf',x->>'whyItFits','topics',x->>'title')) FROM jsonb_array_elements(rebuilt) x)),
  gemini_results=coalesce(gemini_results,'{}'::jsonb)||jsonb_build_object(
    'careerFit',career,'overallSummary',summary,'profileNarrative',jsonb_build_object('summary',summary),
    'demo',true,'assessmentProvenance','Authored local demonstration tracks and fit percentages; not an administered career evaluation.')
 WHERE id='ebef6f55-97ce-5d80-b453-4566ac838d33'
 AND learner_id=(SELECT id FROM public.learners WHERE user_id='6d1c48f6-b3a9-57fb-998c-6a7255713e0c' AND email='aaditya.raman10@example.com')
 AND attempt_id='5cff6ce4-73ff-5b46-937b-56691bfd7326';
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'Apply Aaditya development assessment seed 03 first'; END IF;
 UPDATE public.personal_assessment_results SET
  gemini_results=jsonb_set(jsonb_set(gemini_results,'{skillGap}',skill_gap),'{streamRecommendation,careerPaths}',
    (SELECT jsonb_agg(x->>'name') FROM jsonb_each(groups) g CROSS JOIN LATERAL jsonb_array_elements(g.value) x))
 WHERE id='ebef6f55-97ce-5d80-b453-4566ac838d33';
END $tracks$;

-- WATER PROJECT MANAGER FIRST
-- LOCAL SCHOOL DEMO: show PM first; preserve role objects and IDs.

DO $pm$
DECLARE fit jsonb; first_cluster jsonb; sorted_options jsonb;
BEGIN
 SELECT r.career_fit INTO STRICT fit FROM public.personal_assessment_results r JOIN public.learners l ON l.id=r.learner_id
 WHERE r.id='ebef6f55-97ce-5d80-b453-4566ac838d33' AND l.email='aaditya.raman10@example.com' FOR UPDATE OF r;
 IF (SELECT count(*) FROM jsonb_array_elements(fit#>'{specificOptions,highFit}') o WHERE o->>'name'='Water Project Manager')<>1 THEN RAISE EXCEPTION 'Expected one PM role'; END IF;
 SELECT jsonb_agg(value ORDER BY CASE WHEN value->>'name'='Water Project Manager' THEN 0 ELSE 1 END,position)
 INTO sorted_options FROM jsonb_array_elements(fit#>'{specificOptions,highFit}') WITH ORDINALITY a(value,position);
 fit:=jsonb_set(fit,'{specificOptions,highFit}',sorted_options);
 first_cluster:=fit#>'{clusters,0}';
 first_cluster:=jsonb_set(first_cluster,'{examples}',(SELECT jsonb_agg(o->>'name' ORDER BY position) FROM jsonb_array_elements(sorted_options) WITH ORDINALITY a(o,position)));
 first_cluster:=jsonb_set(first_cluster,'{occupationIds}',(SELECT jsonb_agg(o->>'occupationId' ORDER BY position) FROM jsonb_array_elements(sorted_options) WITH ORDINALITY a(o,position)));
 first_cluster:=jsonb_set(first_cluster,'{roles,entry}',first_cluster->'examples');
 fit:=jsonb_set(fit,'{clusters,0}',first_cluster);
 UPDATE public.personal_assessment_results SET career_fit=fit,gemini_results=jsonb_set(coalesce(gemini_results,'{}'::jsonb),'{careerFit}',fit)
 WHERE id='ebef6f55-97ce-5d80-b453-4566ac838d33';
END $pm$;

-- OPTIONAL EXISTING LOCAL SUBSCRIPTION CACHE GRANT (SSO GRANT REQUIRED FIRST)
-- LOCAL DEMO ONLY. Apply sso-worker's matching 14 seed first.
-- Mirrors that exact SSO grant into Aaditya's existing subscription cache.


UPDATE public.subscription_cache
SET features=coalesce(features,'[]'::jsonb)||'["ai_job_matching"]'::jsonb,
    synced_at=now(), auth_updated_at=now()
WHERE id='9df777e6-f9fd-54c4-bd74-a9d970913e2a'
  AND user_id='6d1c48f6-b3a9-57fb-998c-6a7255713e0c'
  AND plan_code='premium' AND status='active' AND subscription_end_date>now()
  AND NOT coalesce(features,'[]'::jsonb) @> '["ai_job_matching"]'::jsonb;
COMMIT;
